const solutions={retail:{label:'ОТ АССОРТИМЕНТА ДО ОНЛАЙН-ВИТРИНЫ',title:'Новые товары —<br>быстрее на витрину.',description:'Заполняем каталог, приводим данные поставщиков к вашей информационной модели и поддерживаем качество карточек при росте ассортимента.',cta:'Обсудить каталог',items:[['Создание и обогащение карточек','Характеристики, описания и изображения в едином стандарте вашего магазина.'],['Аудит и качество данных','Находим пробелы, несоответствия и дубли. Разрабатываем правила и проверяем результат.'],['Контент для всех каналов','Адаптируем каталог под информационные модели и форматы нужных площадок.']]},market:{label:'ОТ КАТАЛОГА СЕЛЛЕРА ДО ПУБЛИКАЦИИ',title:'Больше ассортимента.<br>Меньше ручной работы.',description:'Помогаем обрабатывать каталоги продавцов, сопоставлять категории и атрибуты, улучшать контент и выстраивать модерацию данных.',cta:'Обсудить процессы маркетплейса',items:[['Мэппинг и категоризация','Сопоставляем категории, атрибуты и значения с информационной моделью маркетплейса.'],['Модерация и дообогащение','Проверяем карточки, дополняем данные и приводим материалы к правилам площадки.'],['Массовая обработка каталогов','Выстраиваем процесс для больших потоков товаров и новых продавцов.']]},brand:{label:'ОТ ПРОДУКТА ДО ВСЕХ КАНАЛОВ ПРОДАЖ',title:'Ваш бренд.<br>Единый стандарт контента.',description:'Оцифровываем ассортимент, создаём визуальный контент и формируем товарные данные, которые удобно передавать ритейлерам и маркетплейсам.',cta:'Обсудить контент бренда',items:[['Оцифровка и производство','Характеристики, предметная фотосъёмка, описания и инфографика для вашего ассортимента.'],['Единое пространство данных','Организуем товарную информацию и медиаматериалы в PIM/DAM ProductBank.'],['Адаптация и локализация','Готовим материалы под площадки, языки и правила каждого канала продаж.']]}};
const tabs=[...document.querySelectorAll('[data-tab]')];
function setTab(tab){const s=solutions[tab.dataset.tab];tabs.forEach(b=>{const on=b===tab;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});document.querySelector('#solution-panel').setAttribute('aria-labelledby',tab.id);document.querySelector('#solution-title').innerHTML=s.title;document.querySelector('#solution-description').textContent=s.description;document.querySelector('.solution-summary .mini-label').textContent=s.label;document.querySelector('#solution-cta').innerHTML=s.cta+' <span>↗</span>';document.querySelector('#solution-items').innerHTML=s.items.map((x,i)=>'<div class="solution-item"><span>0'+(i+1)+'</span><div><h4>'+x[0]+'</h4><p>'+x[1]+'</p></div></div>').join('')}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>setTab(tab));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();setTab(tabs[next]);tabs[next].focus()}})});setTab(tabs[0]);
const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('#nav');toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');toggle.textContent=open?'×':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Открыть меню');toggle.textContent='☰'}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open'))toggle.click()});
document.querySelector('#brief-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const body='Здравствуйте!\n\nМеня зовут '+f.get('name')+'.\nКомпания: '+f.get('company')+'\nРабочая почта: '+f.get('email')+'\n\nЗадача:\n'+f.get('task')+'\n\nХочу обсудить проект с CloudContent.';window.location.href='mailto:info@cloudcontent.ru?subject='+encodeURIComponent('Проект по товарному контенту — '+f.get('company'))+'&body='+encodeURIComponent(body);const status=document.querySelector('#form-status');status.hidden=false;status.textContent='Письмо подготовлено. Если почтовая программа не открылась, напишите на info@cloudcontent.ru.'});

document.querySelectorAll('[data-brief]').forEach(link=>link.addEventListener('click',()=>{const field=document.querySelector('[name="task"]');if(!field.value.trim())field.value=link.dataset.brief;}));
